import json
import re
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "galaxy.html"
MODEL_ID = "galaxy-model"

DRIVER = r"""
import { points } from './model.mjs';
const at = (t) => points(t);
const stats = (t) => {
  const ps = at(t);
  return ps.map(p => ({ x: +p.x, y: +p.y, r: +p.r, a: Math.atan2(p.y, p.x),
                        d: Math.hypot(p.x, p.y) }));
};
const out = { n: at(0).length, t0: stats(0), t1: stats(12) };
console.log(JSON.stringify(out));
"""


def node():
    return shutil.which("node") or shutil.which("node.exe")


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        cls.model = cls.extract_model(cls.raw)
        cls.data = cls.run_model(cls.model) if cls.model and node() else None

    @staticmethod
    def extract_model(raw):
        m = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>(.*?)</script>' % MODEL_ID,
                      raw, re.S | re.I)
        return m.group(1) if m else None

    @staticmethod
    def run_model(src):
        with tempfile.TemporaryDirectory() as tmp:
            d = Path(tmp)
            (d / "model.mjs").write_text(src, encoding="utf-8")
            (d / "driver.mjs").write_text(DRIVER, encoding="utf-8")
            done = subprocess.run([node(), str(d / "driver.mjs")], capture_output=True,
                                  text=True, timeout=60, cwd=d)
            if done.returncode != 0:
                raise AssertionError("model failed in node: %s" % done.stderr[-800:])
            return json.loads(done.stdout.strip().splitlines()[-1])

    def model_data(self):
        self.assertIsNotNone(self.model,
                             'no <script id="%s"> block found' % MODEL_ID)
        self.assertIsNotNone(node(), "node is required to measure the model")
        self.assertIsNotNone(self.data, "model produced no data")
        return self.data

    # --- the page itself -------------------------------------------------
    def test_is_one_self_contained_html_page(self):
        self.assertRegex(self.raw[:400].lower(), r"<!doctype html", )
        self.assertIn("<canvas", self.raw.lower())

    def test_no_external_requests(self):
        for pat, why in ((r'src\s*=\s*["\'](https?:)?//', "external src"),
                         (r'href\s*=\s*["\'](https?:)?//', "external href"),
                         (r"@import", "css @import"),
                         (r'url\(\s*["\']?(https?:)?//', "external url()"),
                         (r"\bfetch\s*\(", "network fetch"),
                         (r"XMLHttpRequest", "XHR")):
            self.assertIsNone(re.search(pat, self.raw, re.I),
                              "page must be self-contained: found %s" % why)

    def test_animates_with_request_animation_frame(self):
        self.assertIn("requestAnimationFrame", self.raw)

    def test_model_is_separate_from_the_renderer(self):
        self.assertIsNotNone(self.model,
                             'the pure model must live in <script id="%s">' % MODEL_ID)
        for banned in ("getContext", "document.", "window.", "canvas"):
            self.assertNotIn(banned, self.model,
                             "model script must be pure math, found %r" % banned)

    # --- the galaxy, measured -------------------------------------------
    def test_enough_particles(self):
        data = self.model_data()
        self.assertGreaterEqual(data["n"], 400,
                                "a galaxy needs >=400 particles, got %s" % data["n"])
        self.assertLessEqual(data["n"], 20000, "particle count is implausible")

    def test_every_particle_is_finite_and_sized(self):
        for p in self.model_data()["t0"]:
            for k in ("x", "y", "r"):
                self.assertEqual(p[k], p[k], "NaN in particle %s" % k)
                self.assertLess(abs(p[k]), 1e6, "particle %s out of range" % k)
            self.assertGreater(p["r"], 0, "particle radius must be positive")

    def test_core_is_denser_than_the_rim(self):
        ps = self.model_data()["t0"]
        rmax = max(p["d"] for p in ps)
        inner = sum(1 for p in ps if p["d"] < 0.25 * rmax)
        outer = sum(1 for p in ps if p["d"] > 0.75 * rmax)
        self.assertGreater(inner, outer,
                           "core must be denser than rim: %s vs %s" % (inner, outer))

    def test_it_rotates(self):
        data = self.model_data()
        moved = sum(1 for a, b in zip(data["t0"], data["t1"])
                    if abs(a["a"] - b["a"]) > 1e-6)
        self.assertGreater(moved, 0.5 * data["n"],
                           "most particles must change angle over 12s; only %s did" % moved)

    def test_rotation_is_differential(self):
        """Inner particles must sweep more angle than outer ones - that is what winds
        the arms. Uniform rotation would make it a turntable, not a galaxy."""
        data = self.model_data()
        pairs = list(zip(data["t0"], data["t1"]))
        rmax = max(p["d"] for p, _ in pairs) or 1.0

        def sweep(lo, hi):
            sel = [abs(b["a"] - a["a"]) for a, b in pairs if lo * rmax <= a["d"] < hi * rmax]
            sel = [s if s < 3.14159 else 6.28318 - s for s in sel]
            return sum(sel) / len(sel) if sel else None
        inner, outer = sweep(0.05, 0.3), sweep(0.6, 1.01)
        self.assertIsNotNone(inner, "no inner particles to measure")
        self.assertIsNotNone(outer, "no outer particles to measure")
        self.assertGreater(inner, outer * 1.15,
                           "rotation is not differential: inner sweep %.4f vs outer %.4f"
                           % (inner, outer))

    def test_spiral_arms_exist(self):
        """Arms mean the particles are not spread evenly around the circle: bin by angle
        and require the busiest bins to clearly beat a uniform spread."""
        ps = self.model_data()["t0"]
        bins = [0] * 36
        for p in ps:
            bins[int((p["a"] + 3.14159) / 6.28318 * 36) % 36] += 1
        avg = sum(bins) / len(bins)
        peak = max(bins)
        self.assertGreater(peak, 1.6 * avg,
                           "no angular structure: peak bin %s vs mean %.1f (arms missing)"
                           % (peak, avg))

    def test_palette_has_warm_and_cool_accents(self):
        colors = re.findall(r"#[0-9a-fA-F]{6}\b", self.raw)
        colors += re.findall(r"hsl\(\s*(\d+)", self.raw)
        self.assertTrue(colors, "no colours declared")
        self.assertTrue(re.search(r"(#[0-9a-fA-F]{6}|hsla?\()", self.raw))


if __name__ == "__main__":
    unittest.main()
